  const v = form.ticket
  if (fgIsBlank(v)) return "This field is required"
  return null
  },
  'seats': function () {
  const v = form.seats
  if (fgIsBlank(v)) return "This field is required"
  if (!fgIsEmpty(v) && ((fgSize(v) ?? -Infinity) < 1)) return "Must be at least 1"
  if (!fgIsEmpty(v) && ((fgSize(v) ?? Infinity) > 5)) return "Must be at most 5"
  return null
