}

function buildPayload(): Record<string, unknown> {
  return {
    "first_name": form.first_name,
    "last_name": form.last_name,
    "email": form.email,
    "phone": form.phone,
    "ticket": form.ticket,
    "seats": form.seats,
    "diet": form.diet,
    ...(fgVisible_diet_other() ? { "diet_other": form.diet_other } : {}),
    "workshops": form.workshops,
    "arrival": form.arrival,
    "notes": form.notes,
    "terms": form.terms,
  }
}

async function onSubmit(): Promise<void> {
  if (!validateAll()) {
    fgAnnounce(fgErrorsText(Object.keys(errors).length))
    return
